// agentdeck-opencode-plugin v6 — AUTO-GENERATED by AgentDeck.
// Do not edit: reinstalls overwrite this file. Remove it (or set
// AGENTDECK_NO_OPENCODE_HOOKS=1 before installing) to opt out.
//
// Forwards OpenCode lifecycle events to the AgentDeck daemon as
// opencode_* hooks — the same observed-session pipeline Claude Code and
// Codex use — so standalone `opencode` sessions appear on the AgentDeck
// timeline with the same prompt → response turn shape. Every POST is
// fire-and-forget with a hard timeout; OpenCode never blocks on AgentDeck.

import { readFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

const NATIVE_OBSERVER = true;
const nativeReceiverURL = new URL("./agentdeck-connection.json", import.meta.url);
const PORT_TTL_MS = 60000;
let cachedPort = null;
let cachedAt = 0;

// Keep at most one OS read per known registry path in flight. An OS consent
// decision can outlive AbortSignal, so the race also bounds the caller while
// the map prevents retries from exhausting the filesystem worker pool.
const registryReads = new Map();
function readRegistry(path) {
  if (registryReads.has(path)) return registryReads.get(path);
  let timer;
  const io = readFile(path, { encoding: "utf-8", signal: AbortSignal.timeout(200) });
  const bounded = Promise.race([io, new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error("registry read timed out")), 200);
  })]);
  registryReads.set(path, bounded);
  const settled = () => { clearTimeout(timer); registryReads.delete(path); };
  io.then(settled, settled);
  return bounded;
}

async function resolvePort() {
  // The native installation owns an explicit loopback receiver. Re-read on
  // every delivery so a live OpenCode process follows local daemon restarts.
  // Invalid/missing selection never falls through to another daemon.
  if (NATIVE_OBSERVER) {
    try {
      const selection = JSON.parse(await readRegistry(nativeReceiverURL));
      const p = selection.port;
      if (!Number.isInteger(p) || p < 1 || p > 65535) return null;
      const r = await fetch("http://127.0.0.1:" + p + "/health", { signal: AbortSignal.timeout(300) });
      if (!r.ok || (await r.json()).mode !== "daemon") return null;
      return p;
    } catch { return null; }
  }
  const now = Date.now();
  if (cachedPort && now - cachedAt < PORT_TTL_MS) return cachedPort;
  const home = homedir();
  const candidates = [];
  for (const f of [
    join(home, ".agentdeck", "daemon.json"),
    join(home, "Library/Containers/bound.serendipity.agent.deck/Data/Library/Application Support/AgentDeck/daemon.json"),
    join(home, "Library/Group Containers/group.bound.serendipity.agent.deck/daemon.json"),
  ]) {
    try {
      const d = JSON.parse(await readRegistry(f));
      const p = d.httpPort || d.port;
      if (typeof p === "number" && p > 0 && !candidates.includes(p)) candidates.push(p);
    } catch { /* missing/malformed — try next */ }
  }
  if (!candidates.includes(9120)) candidates.push(9120);
  for (const p of candidates) {
    try {
      const r = await fetch("http://127.0.0.1:" + p + "/health", { signal: AbortSignal.timeout(300) });
      if (r.ok) { cachedPort = p; cachedAt = now; return p; }
    } catch { /* dead port — try next */ }
  }
  return null;
}

function post(event, body) {
  resolvePort().then((port) => {
    if (!port) return;
    return fetch("http://127.0.0.1:" + port + "/hooks/" + event, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(NATIVE_OBSERVER ? { ...body, observer_only: true } : body),
      signal: AbortSignal.timeout(800),
    });
  }).catch(() => { /* daemon down — observation is best-effort */ });
}

// ── Steering loop ──
// The daemon queues device commands per session (soft/hard interrupt, prompt
// injection); this loop long-polls GET /opencode/commands and executes them
// through the in-process SDK client — abort is immediate, prompts land even
// while the session is idle. One loop per observed session; stops on
// opencode_stop-less session death via the poll's own error backoff.
const steerLoops = new Set();
// permissionID -> the child session that asked it. A Task-tool child's
// permission is surfaced on its parent's row (a real wait the user must see),
// but OpenCode resolves it against the session that asked.
const permissionSession = new Map();

function startSteerLoop(client, sessionID) {
  if (NATIVE_OBSERVER || !client || steerLoops.has(sessionID)) return;
  steerLoops.add(sessionID);
  (async () => {
    let failures = 0;
    while (steerLoops.has(sessionID)) {
      const port = await resolvePort();
      if (!port) { await new Promise((r) => setTimeout(r, 30000)); continue; }
      try {
        const r = await fetch(
          "http://127.0.0.1:" + port + "/opencode/commands?sid=" + encodeURIComponent(sessionID) + "&wait=25",
          { signal: AbortSignal.timeout(32000) },
        );
        if (!r.ok) throw new Error("poll " + r.status);
        failures = 0;
        const { commands } = await r.json();
        for (const cmd of commands || []) {
          try {
            if (cmd.type === "interrupt") {
              await client.session.abort({ path: { id: sessionID } });
            } else if (cmd.type === "send_prompt" && cmd.text) {
              const body = { parts: [{ type: "text", text: cmd.text }] };
              // promptAsync (POST /session/{id}/prompt_async) returns
              // immediately; session.prompt BLOCKS until the whole assistant
              // turn completes, so the older fallback must not be awaited or
              // it would stall this loop for the entire turn.
              if (client.session.promptAsync) await client.session.promptAsync({ path: { id: sessionID }, body });
              else if (client.session.prompt) client.session.prompt({ path: { id: sessionID }, body }).catch(() => {});
              else if (client.session.chat) client.session.chat({ path: { id: sessionID }, body }).catch(() => {});
            } else if (cmd.type === "permission_respond" && cmd.permissionId) {
              // Resolve a pending OpenCode permission from the device.
              // "once" (not "always") keeps device-approval one-shot.
              if (client.postSessionIdPermissionsPermissionId) {
                await client.postSessionIdPermissionsPermissionId({
                  path: { id: permissionSession.get(cmd.permissionId) || sessionID, permissionID: cmd.permissionId },
                  body: { response: cmd.response === "allow" ? "once" : "reject" },
                });
              }
            }
          } catch { /* one bad command must not kill the loop */ }
        }
      } catch {
        failures += 1;
        // Backoff on repeated failures so a dead daemon costs one probe/30s.
        await new Promise((r) => setTimeout(r, Math.min(30000, 1000 * failures)));
      }
    }
  })();
}

function stopSteerLoop(sessionID) {
  steerLoops.delete(sessionID);
}

export const AgentDeckObserver = async ({ directory, client }) => {
  // Managed `agentdeck opencode` sessions already stream structured SSE
  // events through their session bridge; posting hooks too would
  // double-count every turn. AGENTDECK_PORT marks a managed PTY.
  if (process.env.AGENTDECK_PORT) return {};
  if (NATIVE_OBSERVER && process.env.AGENTDECK_NO_OPENCODE_HOOKS === "1") return {};

  const cwd = directory;
  const announced = new Set();   // sessionIDs whose opencode_session_start was posted
  const userMsgs = new Map();    // user messageID -> sessionID
  const promptSent = new Set();  // user messageIDs whose prompt_submit was posted
  const promptTimers = new Map();// user messageID -> flush timer
  const responses = new Map();   // sessionID -> latest assistant text
  // sessionID -> { model, provider } of the turn's latest assistant message.
  // Every assistant message.updated carries modelID/providerID, the first one
  // included (10,474 of 10,474 in OpenCode 1.18.35's own event log,
  // 2026-10-18); the stop is the only hook that tells the daemon which model
  // answered, so APME turns from this plugin carried no model at all.
  const models = new Map();
  const startedAt = new Map();   // sessionID -> turn start ms
  const toolPhase = new Map();   // tool callID -> "start" | "end"
  const parentOf = new Map();    // sessionID -> parent sessionID, or null (top level)
  const childStarted = new Set();// child sessionIDs whose opencode_subagent_start was posted
  const childStopped = new Set();// child sessionIDs whose opencode_subagent_stop was posted
  // Background work (OpenCode 1.18 background subagents, measured 2026-10-11):
  // the task tool part completes at once with state.metadata.background and a
  // jobId (the child session id); the end arrives as a synthetic user text
  // <task id="JOB" state="completed"> on the parent.
  const backgroundStarted = new Set(); // jobIds whose opencode_background_start was posted
  const backgroundFinished = new Set();// jobIds whose opencode_background_finish was posted
  const TASK_RESULT = /<task id="([^"]{1,256})" state="([a-z_]{1,40})">/g;

  function noteBackgroundStart(sessionID, part) {
    const meta = part.state && part.state.metadata;
    const job = meta && meta.background === true && typeof meta.jobId === "string" ? meta.jobId : "";
    if (!job || job.length > 256 || backgroundStarted.has(job)) return;
    if (backgroundStarted.size > 512) backgroundStarted.clear();
    backgroundStarted.add(job);
    post("opencode_background_start", { session_id: sessionID, item_id: job, cwd });
  }

  function noteBackgroundResults(sessionID, text) {
    if (text.indexOf("<task id=") < 0) return;
    for (const m of text.matchAll(TASK_RESULT)) {
      if (m[2] === "running" || backgroundFinished.has(m[1])) continue;
      if (backgroundFinished.size > 512) backgroundFinished.clear();
      backgroundFinished.add(m[1]);
      post("opencode_background_finish", { session_id: sessionID, item_id: m[1], status: m[2], cwd });
    }
  }

  function noteSessionInfo(info) {
    if (!info || typeof info.id !== "string" || !info.id) return;
    parentOf.set(info.id, typeof info.parentID === "string" && info.parentID ? info.parentID : null);
    if (parentOf.size > 512) parentOf.delete(parentOf.keys().next().value);
  }

  // A Task-tool child session (OpenCode sets parentID) is its parent's
  // subagent, not a session the user opened: announcing it put a second row
  // on every deck for the length of the task. session.created normally names
  // the parent first; otherwise ask the server once, bounded. An unanswered
  // lookup is unknown and keeps the old behaviour (a row) — it never hides one.
  // OpenCode calls plugin event handlers WITHOUT awaiting them, so every
  // event of an uncached session would race its own lookup and resume out of
  // order (a prompt landing after its own stop opened a phantom turn). One
  // in-flight promise per session makes them all resume in arrival order.
  const parentLookups = new Map(); // sessionID -> Promise<parent|null>
  function lookupParent(sessionID) {
    if (parentOf.has(sessionID)) return Promise.resolve(parentOf.get(sessionID));
    const pending = parentLookups.get(sessionID);
    if (pending) return pending;
    const lookup = (async () => {
      let parent = null;
      try {
        if (client && client.session && client.session.get) {
          const res = await Promise.race([
            client.session.get({ path: { id: sessionID } }),
            new Promise((r) => setTimeout(() => r(null), 1000)),
          ]);
          const info = res && (res.data || res);
          if (info && typeof info.parentID === "string" && info.parentID) parent = info.parentID;
        }
      } catch { /* unknown → top level */ }
      if (!parentOf.has(sessionID)) parentOf.set(sessionID, parent);
      parentLookups.delete(sessionID);
      return parentOf.get(sessionID);
    })();
    parentLookups.set(sessionID, lookup);
    return lookup;
  }

  /** The top-level session a (possibly nested) child belongs to, or null. */
  async function rootSession(sessionID) {
    if (!sessionID) return null;
    let root = null;
    let cur = sessionID;
    for (let hop = 0; hop < 8; hop++) {
      const parent = await lookupParent(cur);
      if (!parent) break;
      root = parent;
      cur = parent;
    }
    return root;
  }

  function eventSessionID(type, props) {
    if (type === "message.updated") return (props.info || {}).sessionID;
    if (type === "message.part.updated") return (props.part || {}).sessionID;
    if (type === "permission.asked" || type === "permission.updated" || type === "permission.replied") {
      const perm = (props.permission && typeof props.permission === "object") ? props.permission : (props.info || props);
      return perm.sessionID;
    }
    return props.sessionID;
  }

  /** Child-session events: lifecycle into the parent's subagent census, a
   *  genuine permission wait onto the parent's row, everything else dropped. */
  function childEvent(type, props, sessionID, parent) {
    // After its stop, a child stays finished: OpenCode re-emits
    // message.updated once a turn settles, and treating that as a new start
    // left the parent's census showing a running child for hours. Only a new
    // user message (the Task tool resuming the child) starts it again.
    if (childStopped.has(sessionID)) {
      const info = props.info || {};
      const resumed = type === "message.updated" && info.role === "user" && info.id && !userMsgs.has(info.id);
      if (!resumed) return;
      childStopped.delete(sessionID);
    }
    if (!childStarted.has(sessionID)) {
      childStarted.add(sessionID);
      if (childStarted.size > 512) childStarted.delete(childStarted.values().next().value);
      const info = props.info || {};
      const label = typeof info.agent === "string" && info.agent ? info.agent
        : (typeof info.mode === "string" && info.mode ? info.mode : "Subagent");
      post("opencode_subagent_start", { session_id: parent, agent_id: sessionID, agent_type: label, cwd });
    }
    if (type === "message.part.updated") {
      const part = props.part || {};
      if (part.type === "text" && typeof part.text === "string" && !userMsgs.has(part.messageID)) {
        responses.set(sessionID, part.text);
      }
    } else if (type === "message.updated") {
      const info = props.info || {};
      if (info.role === "user" && info.id) userMsgs.set(info.id, sessionID);
    } else if (type === "permission.asked" || type === "permission.updated") {
      const perm = (props.permission && typeof props.permission === "object") ? props.permission : (props.info || props);
      if (perm.id) {
        permissionSession.set(perm.id, sessionID);
        if (permissionSession.size > 256) permissionSession.delete(permissionSession.keys().next().value);
        post("opencode_permission_asked", {
          session_id: parent,
          permission_id: perm.id,
          title: typeof perm.title === "string" ? perm.title : (typeof perm.permission === "string" ? perm.permission : "Permission requested"),
          cwd,
        });
      }
    } else if (type === "permission.replied") {
      const perm = (props.permission && typeof props.permission === "object") ? props.permission : (props.info || props);
      const id = perm.requestID || perm.permissionID || perm.id || "";
      permissionSession.delete(id);
      post("opencode_permission_replied", { session_id: parent, permission_id: id, cwd });
    } else if (type === "question.asked") {
      // Display-only on every surface, so the parent's row can show it.
      if (props.id) {
        post("opencode_question_asked", {
          session_id: parent, question_id: props.id,
          title: (Array.isArray(props.questions) ? props.questions : []).map(q => q.question || q.header || "").filter(Boolean).join(" / "),
          cwd,
        });
      }
    } else if (type === "question.replied" || type === "question.rejected") {
      if (props.requestID) {
        post(type === "question.replied" ? "opencode_question_replied" : "opencode_question_rejected", {
          session_id: parent, question_id: props.requestID, cwd,
        });
      }
    } else if (type === "session.idle") {
      childStarted.delete(sessionID);
      childStopped.add(sessionID);
      if (childStopped.size > 512) childStopped.delete(childStopped.values().next().value);
      post("opencode_subagent_stop", {
        session_id: parent, agent_id: sessionID,
        last_assistant_message: responses.get(sessionID) || "", cwd,
      });
      responses.delete(sessionID);
    }
  }

  function announce(sessionID) {
    if (!sessionID || announced.has(sessionID)) return;
    announced.add(sessionID);
    post("opencode_session_start", { session_id: sessionID, cwd });
    // Steering: start draining device commands for this session (abort /
    // prompt injection through the in-process client). Loop lives for the
    // opencode process lifetime — sessions in one TUI are few and cheap.
    startSteerLoop(client, sessionID);
  }

  function sendPrompt(messageID, sessionID, prompt) {
    if (promptSent.has(messageID)) return;
    promptSent.add(messageID);
    const t = promptTimers.get(messageID);
    if (t) { clearTimeout(t); promptTimers.delete(messageID); }
    if (!startedAt.has(sessionID)) startedAt.set(sessionID, Date.now());
    post("opencode_user_prompt_submit", { session_id: sessionID, prompt: prompt || "", cwd });
  }

  return {
    event: async ({ event }) => {
      try {
        const type = event.type;
        const props = event.properties || {};
        if (type === "session.created" || type === "session.updated") {
          noteSessionInfo(props.info);
          return;
        }
        const eventSid = eventSessionID(type, props);
        const parent = eventSid ? await rootSession(eventSid) : null;
        if (parent) {
          childEvent(type, props, eventSid, parent);
          return;
        }
        if (type === "message.updated") {
          const info = props.info || {};
          const sessionID = info.sessionID;
          announce(sessionID);
          if (info.role === "user" && info.id) {
            // userMsgs/promptSent are dedup memory keyed on user messageID and
            // must outlive the turn (see the session.idle note), so cap them
            // here instead of clearing per turn — same bound as toolPhase.
            if (userMsgs.size > 512) userMsgs.clear();
            if (promptSent.size > 512) promptSent.clear();
            userMsgs.set(info.id, sessionID);
            // Prompt text usually streams via message.part.updated moments
            // later; flush immediately when the info carries it, otherwise
            // wait briefly so the chat_start row shows the real prompt.
            const direct = typeof info.text === "string" ? info.text
              : (typeof info.content === "string" ? info.content : "");
            if (direct.trim()) {
              sendPrompt(info.id, sessionID, direct.trim());
            } else if (!promptTimers.has(info.id) && !promptSent.has(info.id)) {
              const timer = setTimeout(() => sendPrompt(info.id, sessionID, ""), 800);
              if (typeof timer.unref === "function") timer.unref();
              promptTimers.set(info.id, timer);
            }
          } else if (info.role === "assistant" && typeof info.modelID === "string" && info.modelID.trim()) {
            models.set(sessionID, {
              model: info.modelID.trim().slice(0, 200),
              provider: typeof info.providerID === "string" ? info.providerID.trim().slice(0, 80) : "",
            });
          }
        } else if (type === "message.part.updated") {
          const part = props.part || {};
          const sessionID = part.sessionID;
          announce(sessionID);
          if (part.type === "text" && typeof part.text === "string") {
            noteBackgroundResults(sessionID, part.text);
            const owner = userMsgs.get(part.messageID);
            if (owner) sendPrompt(part.messageID, owner, part.text.trim());
            else responses.set(sessionID, part.text);
          } else if (part.type === "tool" && part.callID) {
            const status = (part.state && part.state.status) || "running";
            if (part.tool === "task") noteBackgroundStart(sessionID, part);
            const phase = toolPhase.get(part.callID);
            if (status === "completed" || status === "error") {
              if (phase !== "end") {
                toolPhase.set(part.callID, "end");
                post("opencode_tool_end", { session_id: sessionID, tool_name: part.tool || "tool", tool_use_id: part.callID, is_error: status === "error", cwd });
              }
            } else if (!phase && status !== "pending") {
              toolPhase.set(part.callID, "start");
              const command = part.state?.input?.command;
              const tool_input = part.tool === "bash" && typeof command === "string" && command.length <= 4096
                ? { command } : undefined;
              post("opencode_tool_start", { session_id: sessionID, tool_name: part.tool || "tool", tool_use_id: part.callID, tool_input, cwd });
            }
            if (toolPhase.size > 512) toolPhase.clear();
          }
        } else if (type === "permission.asked" || type === "permission.updated") {
          // OpenCode emits this only when it is GENUINELY asking the user —
          // no prediction needed, zero false-positive risk. Forward it so
          // devices can render Allow/Deny; the daemon replies through the
          // steering queue as a permission_respond command.
          const perm = (props.permission && typeof props.permission === "object") ? props.permission : (props.info || props);
          const psid = perm.sessionID;
          if (psid && perm.id) {
            announce(psid);
            post("opencode_permission_asked", {
              session_id: psid,
              permission_id: perm.id,
              title: typeof perm.title === "string" ? perm.title : (typeof perm.permission === "string" ? perm.permission : "Permission requested"),
              cwd,
            });
          }
        } else if (type === "permission.replied") {
          const perm = (props.permission && typeof props.permission === "object") ? props.permission : (props.info || props);
          const psid = perm.sessionID;
          if (psid) {
            post("opencode_permission_replied", {
              session_id: psid,
              permission_id: perm.requestID || perm.permissionID || perm.id || "",
              cwd,
            });
          }
        } else if (type === "question.asked") {
          if (props.sessionID && props.id) {
            announce(props.sessionID);
            post("opencode_question_asked", {
              session_id: props.sessionID, question_id: props.id,
              title: (Array.isArray(props.questions) ? props.questions : []).map(q => q.question || q.header || "").filter(Boolean).join(" / "),
              cwd,
            });
          }
        } else if (type === "question.replied" || type === "question.rejected") {
          if (props.sessionID && props.requestID) {
            post(type === "question.replied" ? "opencode_question_replied" : "opencode_question_rejected", {
              session_id: props.sessionID, question_id: props.requestID, cwd,
            });
          }
        } else if (type === "session.idle") {
          const sessionID = props.sessionID;
          announce(sessionID);
          const answered = models.get(sessionID);
          post("opencode_stop", {
            session_id: sessionID,
            last_assistant_message: responses.get(sessionID) || "",
            ...(answered ? { model: answered.model } : {}),
            ...(answered && answered.provider ? { model_provider: answered.provider } : {}),
            cwd,
          });
          responses.delete(sessionID);
          models.delete(sessionID);
          startedAt.delete(sessionID);
          // Do NOT clear userMsgs/promptSent for this session. OpenCode
          // re-emits message.updated for a user message after the turn
          // settles; dropping its promptSent entry let that trailing update
          // re-post opencode_user_prompt_submit, which flips the row back to
          // processing and opens a phantom turn. The session is already idle
          // by then, so no session.idle follows to close it and the row reads
          // WORKING until the 30-min idle TTL evicts it. A messageID is never
          // re-submitted, so these entries are pure dedup memory — bounded
          // where they are added, not here.
        }
      } catch { /* never throw into OpenCode's event loop */ }
    },
  };
};
